add('Longest Consecutive Sequence in an Array', '''    public static int solve(int[] a){ Set<Integer> set=new HashSet<>(); for(int x:a) set.add(x); int best=0; for(int x:set){ if(x!=Integer.MIN_VALUE && set.contains(x-1)) continue; int len=1,y=x; while(y!=Integer.MAX_VALUE && set.contains(y+1)){ y++; len++; } best=Math.max(best,len); } return best; }''', 'System.out.println(solve(new int[]{100,4,200,1,3,2}));','4',
    'Return the longest run of consecutive integer VALUES, regardless of input order. Duplicates do not extend a run.', 'Start expansion only where x-1 is absent. Each unique value is visited once by its run, so repeated expansions are avoided.', 'Expected O(n) time; O(u) space.', 'Start at 1 and walk 2,3,4: length 4. 100 and 200 each form length 1.', 'Guard MIN_VALUE/MAX_VALUE before +/-1 to prevent wraparound.', 'Sort a copy and scan in O(n log n) time, ignoring duplicate values.')
prefix_long = '''    public static int solve(int[] a,long k){
        Map<Long,Integer> first=new HashMap<>(); first.put(0L,-1); long sum=0; int best=0;
        for(int i=0;i<a.length;i++){ sum+=a[i]; Integer at=first.get(sum-k); if(at!=null) best=Math.max(best,i-at); first.putIfAbsent(sum,i); } return best;
    }'''
for title,zero in [('Longest subarray with sum K',False),('Largest Subarray with Sum 0',True)]:
    add(title,prefix_long, 'System.out.println(solve(new int[]{1,-1,2,-2,3},%d));' % (0 if zero else 3), '4' if zero else '5',
        'Return the maximum length of a contiguous subarray summing to %s; empty/no match returns zero.' % ('zero (pass k=0)' if zero else 'k'),
        'If prefix[i]-prefix[j]=k, subarray (j,i] sums to k. Keep the EARLIEST index of each prefix sum to maximize length. Seed prefix 0 at index -1.',
        'Expected O(n) time; O(n) space.', 'Prefixes of [1,-1,2,-2,3] are 1,0,2,0,3; zero prefix at i=3 spans four values from index 0.',
        'Negative values invalidate ordinary sum-based sliding windows. Store prefix sums as long; overwriting earliest indices shortens answers.',
        'Enumerate each start and extend a running sum in O(n²) time/O(1) space.')
for title,xor in [('Count subarrays with given sum',False),('Count subarrays with given xor K',True)]:
    code = '''    public static long solve(int[] a,%s k){ Map<%s,Long> count=new HashMap<>(); count.put(%s,1L); %s prefix=0; long ans=0; for(int x:a){ prefix%sx; ans+=count.getOrDefault(prefix%sk,0L); count.put(prefix,count.getOrDefault(prefix,0L)+1); } return ans; }''' % (
        'int' if xor else 'long','Integer' if xor else 'Long','0' if xor else '0L','int' if xor else 'long','^=' if xor else '+=','^' if xor else '-')
    add(title,code,'System.out.println(solve(new int[]{%s},%d));' % ('4,2,2,6,4' if xor else '1,1,1',6 if xor else 2), '4' if xor else '2',
        'Count all contiguous subarrays whose %s is k; return long.' % ('XOR' if xor else 'sum'),
        'A previous prefix must equal currentPrefix %s k. Add its frequency before inserting current prefix so empty subarrays are excluded. Seed zero with frequency one.' % ('XOR' if xor else 'minus'),
        'Expected O(n) time and O(n) space.', 'Repeated compatible prefix values count multiple start positions; they must be stored as counts rather than just presence.',
        'The answer can be n*(n+1)/2, exceeding int. Sum prefixes also need long.', 'Two nested loops maintaining a running aggregate give O(n²) time and O(1) auxiliary space.')

add('Reverse a String II', '''    public static String solve(String s){ char[] a=s.toCharArray(); for(int l=0,r=a.length-1;l<r;l++,r--){ char t=a[l]; a[l]=a[r]; a[r]=t; } return new String(a); }''', 'System.out.println(solve("java"));','avaj',
    'Reverse a string as UTF-16 code units; ASCII is the intended interview input.', 'Copy to a mutable char array and swap symmetric positions; then construct the result.', 'O(n) time and O(n) result/array space.', 'java -> avaj after swapping j/a and a/v.', 'Surrogate pairs need code-point handling for general Unicode. Strings cannot be modified in place.')
add('Palindrome Check', '''    public static boolean solve(String s){ for(int l=0,r=s.length()-1;l<r;l++,r--) if(s.charAt(l)!=s.charAt(r)) return false; return true; }''', 'System.out.println(solve("level"));','true',
    'Exact, case-sensitive palindrome check; punctuation is not ignored.', 'Compare matching ends. If every pair matches, reversing does not change the sequence.', 'O(n) time and O(1) space.', 'l==l, e==e, then central v ends the scan.', 'Empty string is a palindrome. Normalize separately if a judge ignores punctuation/case.')
add('Largest Odd Number in a String', '''    public static String solve(String s){ for(int i=s.length()-1;i>=0;i--) if((s.charAt(i)-'0')%2==1) return s.substring(0,i+1); return ""; }''', 'System.out.println(solve("35420"));','35',
    'Given a decimal digit string without leading zeros (except "0"), return its largest-valued odd substring, or empty.', 'An odd number ends at an odd digit. The rightmost odd digit permits the longest prefix, which is the largest possible candidate for the contract.', 'O(n) time including the substring copy; O(n) output space.', 'From the right skip 0,2,4; digit 5 is odd, so retain prefix 35.', 'No numeric parsing is needed, so huge strings are supported. Leading-zero variants need a separately defined output normalization.')
add('Longest Common Prefix', '''    public static String solve(String[] a){ if(a.length==0) return ""; int length=a[0].length(); for(int i=1;i<a.length;i++){ length=Math.min(length,a[i].length()); int j=0; while(j<length && a[0].charAt(j)==a[i].charAt(j)) j++; length=j; } return a[0].substring(0,length); }''', 'System.out.println(solve(new String[]{"flower","flow","flight"}));','fl',
    'Return the longest prefix common to every string.', 'Maintain the common-prefix length of all processed strings. Comparing the next string can only shrink that prefix.', 'O(total compared characters) time; O(prefix length) output space.', 'flower/flow -> flow; flow/flight -> fl.', 'Empty input or an empty member yields empty. Null strings are outside the contract.')
add('Isomorphic Strings', '''    public static boolean solve(String s,String t){ if(s.length()!=t.length()) return false; Map<Character,Character> forward=new HashMap<>(),back=new HashMap<>(); for(int i=0;i<s.length();i++){ char a=s.charAt(i),b=t.charAt(i); if(forward.containsKey(a)&&forward.get(a)!=b || back.containsKey(b)&&back.get(b)!=a) return false; forward.put(a,b); back.put(b,a); } return true; }''', 'System.out.println(solve("egg","add"));','true',
    'Return whether a one-to-one mapping of UTF-16 characters changes s into t.', 'Maintain forward and reverse maps. Forward consistency enforces repeated-character matches; reverse consistency prevents two source characters from sharing one destination.', 'Expected O(n) time; O(u) space.', 'e->a, g->d, second g remains d.', 'A forward map alone wrongly accepts ab -> cc. Lengths must match.')
add('Rotate String', '''    public static boolean solve(String s,String goal){ return s.length()==goal.length() && (s+s).contains(goal); }''', 'System.out.println(solve("abcde","cdeab"));','true',
    'Return whether goal is a cyclic rotation of s; empty rotates to empty.', 'Every rotation starts at one position in doubled string s+s. Equal length is essential to prevent accepting shorter substrings.', 'O(n²) worst-case substring search on Java 8; O(n) concatenation space.', 'abcdeabcde contains cdeab starting at index 2.', 'Do not label String.contains as guaranteed linear; use KMP for O(n) search.', 'Try all n rotation offsets in O(n²) time, or use KMP over s+s in O(n).')
add('Valid Anagram', '''    public static boolean solve(String s,String t){ if(s.length()!=t.length()) return false; int[] count=new int[65536]; for(int i=0;i<s.length();i++){ count[s.charAt(i)]++; count[t.charAt(i)]--; } for(int x:count) if(x!=0) return false; return true; }''', 'System.out.println(solve("anagram","nagaram"));','true',
    'Check equal multiplicity of UTF-16 code units; exact case matters.', 'Increment for one string and decrement for the other. All counters zero means each character appears equally often.', 'O(n+65536) time, O(65536) space; the alphabet bound is fixed.', 'Both strings contain a three times, n once, g once, r once, m once.', 'For lowercase letters only, 26 counters suffice. Code-point anagrams need a different representation.', 'Sorting both char arrays costs O(n log n) time and O(n) space.')
add('Sort Characters by Frequency', '''    public static String solve(String s){ Map<Character,Integer> f=new HashMap<>(); for(char c:s.toCharArray()) f.put(c,f.getOrDefault(c,0)+1); List<Character> keys=new ArrayList<>(f.keySet()); keys.sort((a,b)->{ int cmp=Integer.compare(f.get(b),f.get(a)); return cmp!=0?cmp:Character.compare(a,b); }); StringBuilder out=new StringBuilder(); for(char c:keys) for(int i=0;i<f.get(c);i++) out.append(c); return out.toString(); }''', 'System.out.println(solve("tree"));','eert',
    'Sort character groups by descending frequency; ties by ascending UTF-16 character value.', 'Count, sort distinct characters by the contract comparator, then repeat each character its count.', 'Expected O(n+u log u) time; O(n+u) space.', 'e:2, r:1, t:1 -> ee then r then t.', 'Tie-breaking makes output deterministic. Comparator subtraction can overflow for large integer counts; use compare.', 'Frequency buckets can produce O(n+u) time but need explicit tie ordering if required.')
add('Remove Outermost Parentheses', '''    public static String solve(String s){ StringBuilder out=new StringBuilder(); int depth=0; for(char c:s.toCharArray()){ if(c=='('){ if(depth++>0) out.append(c); } else if(c==')'){ if(--depth>0) out.append(c); } else throw new IllegalArgumentException(); if(depth<0) throw new IllegalArgumentException(); } if(depth!=0) throw new IllegalArgumentException(); return out.toString(); }''', 'System.out.println(solve("(()())(())"));','()()()',
    'Remove the outer pair of each primitive component of a balanced parentheses string.', 'Opening at depth zero and closing to depth zero delimit a primitive and are omitted; interior characters are kept.', 'O(n) time, O(n) result space.', '(()()) contributes ()(); (()) contributes ().', 'A primitive has no proper nonempty balanced prefix. Reject malformed input rather than returning a misleading partial string.')
add('Maximum Nesting Depth of the Parentheses', '''    public static int solve(String s){ int depth=0,best=0; for(char c:s.toCharArray()){ if(c=='(') best=Math.max(best,++depth); else if(c==')') depth--; if(depth<0) throw new IllegalArgumentException(); } if(depth!=0) throw new IllegalArgumentException(); return best; }''', 'System.out.println(solve("(1+(2*3)+((8)/4))+1"));','3',
    'Return maximum parentheses nesting in an otherwise arbitrary balanced expression.', 'Track current open parentheses and maximum depth reached. Nonparenthesis characters do not change depth.', 'O(n) time; O(1) space.', 'The ((8)/4) segment sits inside an outer pair, reaching depth 3.', 'Malformed parentheses are rejected; an expression without parentheses has depth zero.')
add('Roman to Integer', '''    private static int value(char c){ switch(c){ case 'I':return 1; case 'V':return 5; case 'X':return 10; case 'L':return 50; case 'C':return 100; case 'D':return 500; case 'M':return 1000; default:throw new IllegalArgumentException(); } }
    public static int solve(String s){ int ans=0; for(int i=0;i<s.length();i++){ int x=value(s.charAt(i)); ans+=i+1<s.length()&&x<value(s.charAt(i+1))?-x:x; } return ans; }''', 'System.out.println(solve("MCMXCIV"));','1994',
    'Convert a valid canonical Roman numeral (normally 1..3999) to integer.', 'A smaller symbol before a larger one is subtractive; all other symbols are additive.', 'O(n) time; O(1) space.', 'M + (-C+M) + (-X+C) + (-I+V) = 1000+900+90+4.', 'This converter assumes valid Roman syntax; it rejects unknown symbols but does not validate canonical repetition rules.')
add('String to Integer (atoi)', '''    public static int solve(String s){ int i=0,sign=1; while(i<s.length()&&s.charAt(i)==' ') i++; if(i<s.length()&&(s.charAt(i)=='+'||s.charAt(i)=='-')) sign=s.charAt(i++)=='-'?-1:1; long v=0,limit=sign==1?Integer.MAX_VALUE:2147483648L; while(i<s.length()&&s.charAt(i)>='0'&&s.charAt(i)<='9'){ int d=s.charAt(i++)-'0'; if(v>(limit-d)/10) return sign==1?Integer.MAX_VALUE:Integer.MIN_VALUE; v=v*10+d; } return (int)(sign*v); }''', 'System.out.println(solve("   -42 words"));','-42',
    'Skip leading ASCII spaces, accept one optional sign, read consecutive decimal digits, and clamp to signed int range. No digits yields zero.', 'Accumulate magnitude. Before multiplying by ten, compare with (limit-digit)/10 so even very long strings cannot overflow the accumulator.', 'O(n) time; O(1) space.', 'Skip spaces, read -, accumulate 4 then 42, stop at the following space.', 'Negative magnitude permits 2147483648; positive permits only 2147483647. Two signs or a nondigit before digits produce zero.')
add('Count Number of Substrings', '''    private static long atMost(String s,int k){ if(k<0) return 0; Map<Character,Integer> count=new HashMap<>(); int l=0; long ans=0; for(int r=0;r<s.length();r++){ char c=s.charAt(r); count.put(c,count.getOrDefault(c,0)+1); while(count.size()>k){ char x=s.charAt(l++); int f=count.get(x)-1; if(f==0) count.remove(x); else count.put(x,f); } ans+=r-l+1; } return ans; }
    public static long solve(String s,int k){ return atMost(s,k)-atMost(s,k-1); }''', 'System.out.println(solve("pqpqs",2));','7',
    'Count substrings with exactly k distinct UTF-16 characters.', 'Exactly k = atMost(k)-atMost(k-1). Each valid at-most window ending at r contributes r-l+1 suffixes.', 'Expected O(n) time; O(u) space.', 'pqpqs has six valid substrings in pqpq with exactly two distinct, plus qs, totaling seven.', 'The source title does not specify a variant; this lesson explicitly chooses exactly k distinct. k<=0 returns zero for nonempty substrings.', 'Directly enumerate substrings and update counts in O(n²) time.')
add('Longest Palindromic Substring', '''    private static int expand(String s,int l,int r){ while(l>=0 && r<s.length() && s.charAt(l)==s.charAt(r)){ l--; r++; } return r-l-1; }
    public static String solve(String s){ int start=0,best=0; for(int i=0;i<s.length();i++){ int len=Math.max(expand(s,i,i),expand(s,i,i+1)); if(len>best){ best=len; start=i-(len-1)/2; } } return s.substring(start,start+best); }''', 'System.out.println(solve("babad"));','bab',
    'Return a longest contiguous palindrome; ties keep the earliest center discovered.', 'Every palindrome has an odd center or an even center between characters. Expand both kinds at every index, retaining the longest.', 'O(n²) worst time; O(1) auxiliary state plus O(answer length) substring output.', 'At center a in babad expand b-a-b; later aba ties length 3 and does not replace bab.', 'Empty input returns empty. Substring and subsequence are different problems.', 'Checking each substring character-by-character costs O(n³). DP takes O(n²) time/space; Manacher can achieve O(n) time.')
add('Sum of Beauty of All Substrings', '''    public static long solve(String s){ long total=0; for(int l=0;l<s.length();l++){ int[] count=new int[26]; for(int r=l;r<s.length();r++){ int x=s.charAt(r)-'a'; if(x<0||x>=26) throw new IllegalArgumentException(); count[x]++; int hi=0,lo=Integer.MAX_VALUE; for(int f:count) if(f>0){ hi=Math.max(hi,f); lo=Math.min(lo,f); } total+=hi-lo; } } return total; }''', 'System.out.println(solve("aabcb"));','5',
    'For lowercase a..z, beauty of a substring is largest minus smallest POSITIVE frequency. Sum over all nonempty substrings.', 'For each left boundary extend right, updating counts. Scan the fixed alphabet for frequency extrema; this avoids recounting the substring from scratch.', 'O(26*n²) time; O(26) auxiliary space.', 'Zero-frequency letters do not affect the minimum; otherwise even a single-character string would incorrectly have positive beauty.', 'Use long total. Nonlowercase input is rejected.', 'Recounting every substring from scratch takes O(n³) time.')
